BEGIN TRANSACTION;
CREATE TABLE properties (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        source TEXT,
        address TEXT UNIQUE,
        city TEXT,
        county TEXT,
        zip TEXT,
        latitude REAL,
        longitude REAL,
        list_price INTEGER,
        price_per_sqft REAL,
        beds INTEGER,
        baths REAL,
        sqft INTEGER,
        lot_sqft INTEGER,
        year_built INTEGER,
        property_type TEXT,
        days_on_market INTEGER,
        hoa_monthly INTEGER,
        listing_remarks TEXT,
        assessed_value INTEGER,
        last_sale_price INTEGER,
        last_sale_date TEXT,
        zoning TEXT,
        deal_score REAL,
        deal_tier TEXT,
        distress_signals TEXT,
        ai_analysis TEXT,
        listing_url TEXT,
        first_seen TEXT,
        last_updated TEXT,
        is_active INTEGER DEFAULT 1
    );
CREATE TABLE scan_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        scan_date TEXT,
        source TEXT,
        properties_scanned INTEGER,
        new_deals_found INTEGER,
        top_deal_address TEXT,
        top_deal_score REAL
    );
DELETE FROM "sqlite_sequence";
COMMIT;
